defmodule Smalt.HwTest do
  use ExUnit.Case, async: false

  alias Smalt.Hw.{Frame, Signer, VirtualSerial}

  doctest Smalt.Hw.Frame

  # -- codec: CRC + framing --------------------------------------------------

  test "CRC-16/CCITT-FALSE witness vector 0x29B1" do
    assert Frame.self_test()
    assert Frame.crc16("123456789") == 0x29B1
    assert Frame.crc16(<<>>) == 0xFFFF
  end

  test "frame parity with the Python/TS codec (witnessed vectors)" do
    # Generated by smalt-cli/smalt_cli/hw/serial.py encode_frame (TS-parity
    # witnessed in smalt_cli/test_hw.py test_wire_parity_against_ts_codec).
    assert Base.decode16!("7E010003CFCB7E") == Frame.encode(<<0x03>>)
    assert Base.decode16!("7E04007D5E7D5DFF0038717E") == Frame.encode(<<0x7E, 0x7D, 0xFF, 0x00>>)

    digest = :binary.copy(<<0xAA>>, 32)
    assert Base.decode16!("7E210001" <> String.duplicate("AA", 32) <> "C1597E") ==
             Frame.encode(<<0x01, digest::binary>>)
  end

  test "frame round trip through the streaming decoder" do
    payload = <<0x01>> <> :binary.copy(<<0xAB>>, 32)
    dec = Frame.push(Frame.decoder(), Frame.encode(payload))
    assert {[^payload], dec} = Frame.take(dec)
    assert dec.frames == []
  end

  test "decoder resync: bad-CRC frame dropped, next good frame decoded" do
    good = Frame.encode(<<0x03>>)
    <<a, b, c, d::binary>> = good
    corrupt = <<a, b, Bitwise.bxor(c, 0xFF), d::binary>>

    dec = Frame.push(Frame.decoder(), corrupt <> good)
    assert {[<<0x03>>], dec2} = Frame.take(dec)
    assert dec2.frames == []
  end

  test "encode rejects oversize payload" do
    assert_raise ArgumentError, fn ->
      Frame.encode(:binary.copy(<<0>>, 4097))
    end
  end

  # -- signer -----------------------------------------------------------------

  test "deterministic Ed25519: same seed, same key, 64-byte sig" do
    sig1 = Signer.sign(<<1::size(256)>>)
    sig2 = Signer.sign(<<1::size(256)>>)
    assert byte_size(sig1) == 64
    assert sig1 == sig2

    {pub, priv} = Signer.keypair()
    assert byte_size(pub) == 32
    assert byte_size(priv) == 32
    assert :crypto.verify(:eddsa, :none, <<1::size(256)>>, sig1, [pub, :ed25519])
  end

  # -- device dispatch ----------------------------------------------------------

  test "enroll -> capabilities with sim-0.1+ed25519" do
    {:ok, pid} = VirtualSerial.start_link(name: :hw_test_dev1)

    caps = VirtualSerial.handle_payload(pid, <<0x03>>)
    <<0x04, se, sha, fw_len, fw::binary-size(fw_len), max::little-integer-size(16)>> = caps
    assert se == 1 and sha == 1
    assert fw == "sim-0.1+ed25519"
    assert max == 4096
  end

  test "sign -> SIGNED_RECEIPT with strictly increasing counter" do
    {:ok, pid} = VirtualSerial.start_link(name: :hw_test_dev2)

    digest = :crypto.hash(:sha256, "challenge")

    r1 = VirtualSerial.handle_payload(pid, <<0x01>> <> digest)
    r2 = VirtualSerial.handle_payload(pid, <<0x01>> <> digest)

    n = byte_size(r1) - 1 - 64 - 4
    assert <<0x02, sig::binary-size(64), serial::binary-size(n), 1::little-integer-size(32)>> = r1
    assert <<0x02, ^sig::binary, serial2::binary-size(n), 2::little-integer-size(32)>> = r2

    assert serial == serial2 and byte_size(serial) > 0
  end

  test "unknown type -> 0x7F ERROR UNKNOWN_TYPE; short digest -> BAD_DIGEST" do
    {:ok, pid} = VirtualSerial.start_link(name: :hw_test_dev3)

    err = VirtualSerial.handle_payload(pid, <<0xAB, 0x00>>)
    assert <<0x7F, 2, "unknown message type 0xab">> = err

    bad = VirtualSerial.handle_payload(pid, <<0x01, 1, 2, 3>>)
    assert <<0x7F, 4, _msg::binary>> = bad
  end
end